INSERT INTO `configuration` (`configuration_title`, `configuration_key`, `configuration_value`, `configuration_description`, `configuration_group_id`, `sort_order`, `last_modified`, `date_added`, `use_function`, `set_function`, `val_function`) VALUES
('FraudLabs Pro - Enable Agent Javascript', 'FRAUDLABSPRO_AGENTJS', 'false', 'Enable FraudLabs Pro <a href="https://www.fraudlabspro.com/developer/javascript" target="_blank">Agent Javascript</a>. This will install a cookie during a customer\'s checkout that will attach the client Agent, Browser, Operating System, and Device Type to the transaction being processed in FraudLabs Pro. This is completely optional but will cause the API to not report if the device has been blacklisted or not.<br><em>True</em> - Enable Agent Javascript<br><br><em>False</em> - Disable Agent Javascript', 1, 52, NOW(), NOW(), NULL, 'zen_cfg_select_option(array(\'true\', \'false\'),', NULL);
